    Some(format!(
        "|cnIQ{}:|Hitem:{}::::::::80:70:::::::::|h[{}]|h|r",
        item.quality, item_id, item.name
    ))
}

pub(crate) fn spell_link_for_id(spell_id: u32) -> Option<String> {
